def solution(input_data: str) -> str:
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse events
    events = []
    for i in range(1, len(lines)):
        parts = lines[i].split()
        if parts[0] == '1':
            events.append((1, None))
        else:
            events.append((2, parts[1]))

    # Since first event is always type 1, we have segments between type 1 events
    # Collect all friend names that appear
    friend_names = set()
    for _, friend in events:
        if friend is not None:
            friend_names.add(friend)

    # Map each friend to their index
    friend_to_idx = {name: i + 1 for i, name in enumerate(sorted(friend_names))}
    num_friends = len(friend_names)

    # Collect segments (periods between type 1 events)
    segments = []
    current_segment = []

    for event in events:
        if event[0] == 1:
            if current_segment:
                segments.append(current_segment)
                current_segment = []
            # After type 1, start new segment
        else:
            friend = event[1]
            if friend is not None and friend in friend_to_idx:
                current_segment.append(friend_to_idx[friend])

    if current_segment:
        segments.append(current_segment)

    # If no type 1 events after first, we still have the initial segment
    # Actually, since first event is 1, we collected segments between 1s

    # Build conflict graph: if two friends ever appear in same segment, they conflict
    conflict = [[False] * (num_friends + 1) for _ in range(num_friends + 1)]

    for segment in segments:
        seen = set()
        for friend_idx in segment:
            for prev in seen:
                conflict[prev][friend_idx] = conflict[friend_idx][prev] = True
            seen.add(friend_idx)

    # Count occurrences across segments (not needed for independent set but useful)
    # For maximum independent set with n ≤ 40 friends, we use bitmask DP

    # Build adjacency list for faster lookup
    conflict_list = [[] for _ in range(num_friends + 1)]
    for i in range(1, num_friends + 1):
        for j in range(1, num_friends + 1):
            if conflict[i][j]:
                conflict_list[i].append(j)

    # Maximum Independent Set using bitmask DP
    # Since m ≤ 40, we need efficient solution
    # Max independent set is NP-hard, but for 40 bits we can use DFS with pruning

    max_happy = 0

    def can_add(mask, friend):
        """Check if we can add friend to current set"""
        for other in conflict_list[friend]:
            if (mask & (1 << other)) != 0:
                return False
        return True

    def dfs(mask, count):
        nonlocal max_happy

        # Pruning: if remaining capacity can't beat current max, skip
        remaining = num_friends - bin(mask).count('1')
        if count + remaining <= max_happy:
            return

        max_happy = max(max_happy, count)

        # Try adding each friend not in mask
        for friend in range(1, num_friends + 1):
            if (mask & (1 << friend)) == 0 and can_add(mask, friend):
                dfs(mask | (1 << friend), count + 1)

    dfs(0, 0)

    return str(max_happy)

