def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def get_prime_factors(n):
    """Get all prime factors of n."""
    factors = set()
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.add(d)
            n //= d
        d += 1
    if n > 1:
        factors.add(n)
    return factors

def solve_case(data):
    lines = data.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    if n == 1 and a[0] <= 1:
        return "-1\n"

    total = sum(a)
    if total == 1:
        return "-1\n"

    prime_factors = get_prime_factors(total)

    def compute_cost(k):
        rem = 0
        cost = 0
        for x in a:
            rem += (x % k)
            cost += abs(rem)
        return cost // 2

    min_moves = float('inf')
    for k in prime_factors:
        moves = compute_cost(k)
        if moves < min_moves:
            min_moves = moves

    return f"{min_moves}\n"

