MOD = 1000000007

def factorial(n):
    """Calculate n! modulo MOD."""
    if n < 0:
        return 0
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % MOD
    return result

def nCr(n, r):
    """Calculate n choose r modulo MOD using Fermi's little theorem for modular inverse."""
    if r < 0 or r > n:
        return 0
    numerator = factorial(n)
    denominator = factorial(r) * factorial(n - r)
    inv_denom = pow(denominator, MOD - 2, MOD)
    return (numerator * inv_denom) % MOD

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    # Find positions with -1 (using 1-indexed positions)
    missing_positions = []
    present_values = set()

    for i in range(n):
        if a[i] == -1:
            missing_positions.append(i + 1)  # Store 1-indexed position
        else:
            present_values.add(a[i])

    # Find missing values (values not yet used in the permutation)
    missing_values = set(range(1, n + 1)) - present_values

    # Count conflicts: positions i where a[i] == -1 and the position number i equals a missing value
    # These are fixed points we must avoid
    conflicts = 0
    for pos in missing_positions:
        if pos in missing_values:
            conflicts += 1

    k = len(missing_positions)

    # Use inclusion-exclusion principle to count valid derangements
    # We need to avoid placing value i at position i for the 'conflicts' positions
    ans = 0
    for i in range(conflicts + 1):
        term = nCr(conflicts, i) * factorial(k - i)
        if i % 2 == 0:
            ans = (ans + term) % MOD
        else:
            ans = (ans - term + MOD) % MOD

    return str(ans)


