MOD = 1000000007

def poly_mul(a, b, mod):
    """Multiply two polynomials modulo x^deg."""
    result = []
    i_deg = len(a) - 1
    j_deg = len(b) - 1

    total_len = i_deg + j_deg + 1
    res = [0] * total_len

    for i in range(len(a)):
        if a[i] == 0:
            continue
        for j in range(len(b)):
            if b[j] == 0:
                continue
            res[i + j] = (res[i + j] + a[i] * b[j]) % mod

    # Trim to meaningful length
    while res and res[-1] == 0:
        res.pop()
    return res if res else [0]

def poly_pow(poly, exp, max_deg, mod):
    """Compute poly^exp truncated to degree max_deg."""
    result = [1]
    base = poly[:]

    while exp > 0:
        if exp & 1:
            result = poly_mul(result, base)
            while len(result) > max_deg + 1:
                result = result[:-1]
        base = poly_mul(base, base)
        while len(base) > max_deg + 1:
            base = base[:-1]
        exp >>= 1

    return result

