def get_prime_factors(num):
    """Get all prime factors of num."""
    factors = set()
    d = 2
    temp = num
    while d * d <= temp:
        while temp % d == 0:
            factors.add(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return sorted(list(factors))

