import math

MOD = 1000000007

def is_good(perm):
    """Check if a permutation forms a good array"""
    r = len(perm)
    if r < 2:
        return False
    # Check all adjacent pairs including wraparound
    for i in range(r):
        if abs(perm[i] - perm[(i + 1) % r]) != 1:
            return False
    return True

