    result = 0

    # For each possible array length r from 1 to n
    for r in range(1, n + 1):
        # Generate non-decreasing arrays (combinations with replacement)
        for combo in combinations_with_replacement(range(1, m + 1), r):
            # Check all distinct permutations
            all_perms = set(permutations(combo))
            good_perms = [p for p in all_perms if is_good(p)]

            # Check if it can form at least 1 and at most k distinct good arrays
            if 1 <= len(good_perms) <= k:
                result += 1
                result %= MOD

    return str(result)


