    sys.stdin = __import__('io').StringIO(input_str)
    lines = sys.stdin.read().split('\n')

    if not lines:
        return "NO"

    n = int(lines[0])
    strings = []
    for i in range(1, n):
        if i < len(lines):
            strings.append(lines[i])

    if len(strings) != n:
        return "NO"

    # Map each string to its most frequent character
    def get_most_frequent(s):
        freq = defaultdict(int)
        for c in s:
            freq[c] += 1
        if not freq:
            return None
        max_freq = max(freq.values())
        return [c for c, cnt in freq.items() if cnt == max_freq]

    str_mf = [get_most_frequent(s) for s in strings]

    for mf in str_mf:
        if not mf:
            return "NO"

    # All strings must have same MF characters
    valid_chars = set(str_mf[0])
    for mf in str_mf[1:]:
        if set(mf) != valid_chars:
            return "NO"

    # Build DAG of substring relationships
    adj = defaultdict(list)

    for i in range(n):
        for j in range(n):
            if i != j and strings[i] in strings[j] and strings[j] not in strings[i] and strings[i] not in strings:
                # strings[i] is substring of strings[j]
                adj[j].append(i)

    # Check for cycles
    def has_cycle():
        visited = [False] * n
        rec_stack = [False] * n

        def dfs(u):
            visited[u] = True
            rec_stack[u] = True
            for v in adj[u]:
                if visited[v]:
                    if rec_stack[v]:
                        return True
                elif v < n:
                    if dfs(v):
                        return True
            rec_stack[u] = False
            return False

        for i in range(n):
            if visited[i]:
                continue
            if dfs(i):
                return True
        return False

    if has_cycle():
        return "NO"

    # Lexicographically minimum string
    result = sorted(strings)
    return '\n'.join(result) + '\n'

