    # dp[i][balance] = True if position i can be reached with this balance
    # balance = wins - loses
    # Valid balances range from -(k-1) to (k-1) during the game
    # At the end, must have balance == k or balance == -k

    balance_range = range(-(k-1), k)

    # dp[i][b] = can reach position i with balance b
    dp = [[False] * len(balance_range) for _ in range(n + 1)]

    # Start position: balance 0
    start_idx = 0
    dp[0][start_idx] = True

    parent = [[None] * len(balance_range) for _ in range(n + 1)]
    choice = [[None] * len(balance_range) for _ in range(n + 1)]  # Stores (char, balance)

    for i in range(n):
        for b_idx, b in enumerate(balance_range):
            if not dp[i][b_idx]:
                continue

            # Determine what characters are allowed at position i
            allowed = set()
            if s[i] == '?':
                allowed = {'W', 'L', 'D'}
            else:
                allowed = {s[i]}

            for char in allowed:
                next_balance = b
                if char == 'W':
                    next_balance += 1
                elif char == 'L':
                    next_balance -= 1
                # D doesn't change balance

                # Check if next_balance is valid (not reaching k or -k before the end)
                if i < n - 1:
                    if next_balance == k or next_balance == -k:
                        continue
                else:
                    # At the end, must have exactly k or -k
                    if next_balance != k and next_balance != -k:
                        continue

                # Calculate next balance index if valid
                b_range = list(balance_range)
                try:
                    next_b_idx = b_range.index(next_balance)
                except ValueError:
                    continue

                if not dp[i + 1][next_b_idx]:
                    dp[i + 1][next_b_idx] = True
                    parent[i + 1][next_b_idx] = (b, char)
                    choice[i + 1][next_b_idx] = char

    # Check if we can reach end with valid balance
    found = False
    for b_idx in range(len(balance_range)):
        if dp[n][b_idx]:
            found = True
            break

    if not found:
        return 'NO\n'

    # Reconstruct the solution
    result = [''] * n
    current_b_idx = 0
    for b_idx in range(len(balance_range)):
        if dp[n][b_idx]:
            current_b_idx = b_idx
            break

    for i in range(n, 0, -1):
        prev_b, char = parent[i][current_b_idx]
        result[i - 1] = char
        current_b_idx = balance_range.index(prev_b)

    return ''.join(result) + '\n'


