def segment_tree():
    """Return a segment tree class for range add and range max query"""
    class SegTree:
        def __init__(self, arr):
            self.n = len(arr)
            self.tree = [0] * (4 * self.n)
            self.lazy = [0] * (4 * self.n)
            self.build(arr, 1, 0, self.n - 1)

        def build(self, arr, node, l, r):
            if l == r:
                self.tree[node] = arr[l]
                return
            mid = (l + r) // 2
            self.build(arr, 2*node, l, mid)
            self.build(arr, 2*node+1, mid+1, r)
            self.tree[node] = max(self.tree[2*node], self.tree[2*node+1])

        def push(self, node):
            if self.lazy[node] != 0:
                self.tree[2*node] += self.lazy[node]
                self.tree[2*node+1] += self.lazy[node]
                self.lazy[2*node] += self.lazy[node]
                self.lazy[2*node+1] += self.lazy[node]
                self.lazy[node] = 0

        def update(self, node, l, r, ql, qr, val):
            if ql > r or qr < l:
                return
            if ql <= l and r <= qr:
                self.tree[node] += val
                self.lazy[node] += val
                return
            self.push(node)
            mid = (l + r) // 2
            self.update(2*node, l, mid, ql, qr, val)
            self.update(2*node+1, mid+1, r, ql, qr, val)
            self.tree[node] = max(self.tree[2*node], self.tree[2*node+1])

        def query_max(self, node, l, r, ql, qr):
            if ql > r or qr < l:
                return float('-inf')
            if ql <= l and r <= qr:
                return self.tree[node]
            self.push(node)
            mid = (l + r) // 2
            left_max = self.query_max(2*node, l, mid, ql, qr)
            right_max = self.query_max(2*node+1, mid+1, r, ql, qr)
            return max(left_max, right_max)

    class MaxMinSegTree:
        """Supports range add, range max, and range min queries"""
        def __init__(self, arr):
            self.n = len(arr)
            self.tree = [float('-inf')] * (4 * self.n)
            self.tree_min = [float('inf')] * (4 * self.n)
            self.lazy = [0] * (4 * self.n)
            self.build(arr, 1, 0, self.n - 1)

        def build(self, arr, node, l, r):
            if l == r:
                self.tree[node] = arr[l]
                self.tree_min[node] = arr[l]
                return
            mid = (l + r) // 2
