                return 0
            if ql <= l and r <= qr:
                return self.tree[node]
            self.push(node)
            mid = (l + r) // 2
            return self.query_sum(2*node, l, mid, ql, qr) + self.query_sum(2*node+1, mid+1, r, ql, qr)

        def calculate_fA(self, node, l, r, ql, qr):
            """Calculate f(A) for range [ql, qr] = sum of (A[i] - A[i-1])^2 for i in [ql+1, qr]"""
            if ql > r or qr < l or ql > qr:
