                if arr[p1] == t1 and arr[p2] != t2:
                    return True
        return False

    def backtrack(pos, chars_so_far):
        nonlocal found

        if found:
            return True

        if pos == n:
            # Check if the complete word satisfies all rules
            if not check_violation(chars_so_far[:]):
                return False
            return True

        # Determine minimum character index to try
        # If we're still matching s, we must use >= s[pos]
        # If we've already diverged, we can use any character (but track minimal)
        min_idx = ord(s[pos]) - ord('a')

        for char_idx in range(min_idx, l):
            char = alphabet[char_idx]
            char_type = 'V' if is_vowel[char] else 'C'

            temp_arr = chars_so_far + [char_type]

            # If current assignment doesn't violate any complete rules
            if not check_violation(temp_arr):
                result[pos] = char

                if backtrack(pos + 1, chars_so_far + [char_type]):
                    found = True
                    return True

                result[pos] = ''

        return False

    if backtrack(0, []):
        return ''.join(result)
    else:
        return "-1"

