def solution(data):
    MOD = 10**9 + 7

    # Parse input
    lines = data.strip().split('\n')
    q = int(lines[0])
    queries = []
    for i in range(1, q + 1):
        r, n = map(int, lines[i].split())
        queries.append((r, n))

    max_n = 1000000

    # Precompute divisors for all numbers up to max_n
    divs = [[] for _ in range(max_n + 1)]
    for i in range(1, max_n + 1):
        for j in range(i, max_n + 1, i):
            divs[j].append(i)

    # Precompute f0(n) = 2^k where k = number of distinct prime factors of n
    f0 = [1] * (max_n + 1)
    for i in range(1, max_n + 2):
        if i <= max_n:
            if f0[1] == 0:
                f0[1] = 1
            f0[i] = 2

    # Mark prime factors
    prime_factor = [False] * (max_n + 1)
    for i in range(2, max_n + 1):
        if not prime_factor[i]:
            for j in range(i, max_n + 1, i):
                prime_factor[j] = True

    # Compute f0
    for i in range(1, max_n + 1):
        distinct_primes = 0
        temp = i
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                distinct_primes += 1
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            distinct_primes += 1
        f0[i] = pow(2, distinct_primes, MOD)

    # XOR precomputation for efficiency
    pow2 = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        pow2[i] = (pow2[i-1] * 2) % MOD

    # Answer queries
    results = []
    for r, n in queries:
        if r == 0:
            results.append(f0[n])
            continue

        # Compute fr(n) by iteratively applying divisor sum
        curr = [0] * (n + 1)
        curr[0] = f0[0] if n >= 0 else 0
        curr[1] = f0[1]
        for i in range(2, n + 1):
            curr[i] = f0[i]

        if r > 0:
            for _ in range(r):
                # f_new[n] = sum of f_old[d] for all d|n
                # Precompute cumulative sums per number
                new_curr = [0] * (n + 1)
                for i in range(1, n + 1):
                    s = 0
                    for d in divs[i]:
                        s = (s + curr[d]) % MOD
                    new_curr[i] = s
                curr = new_curr

        results.append(curr[n])

    # Build output string
    output = '\n'.join(map(str, results))
    return output

