def mat_pow(A, p):
    n = len(A)
    result = [[0]*n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    while p > 0:
        if p % 2 == 1:
            result = mat_mul(result, A)
        A = mat_mul(A, A)
        p //= 2
