    # Construct transformation matrix M
    M = [[0]*3 for _ in range(3)]
    M[0] = [1, 1, 1]  # a_n = a_{n-1} + a_{n-2} + a_{n-3}
    M[1] = [1, 0, 0]  # a_{n-1} = a_{n-1}
    M[2] = [0, 1, 0]  # a_{n-2} = a_{n-2}

