    # Try pairing with each adjacent unused edge
    paths_from_first = adj[u1] + adj[v1]

    for idx, i in enumerate(paths_from_first):
        if not (i[0] in remaining or i[1] == first and not any(e[0] == i[1] and e[1] == first for e in edges)):
            u2, v2 = edges[i]
            if i == first or used[i]:
                continue

            # If we can form a path of length 2
            if i != first:
                # Check if these edges can form a valid path
                # First edge: u1-v1, Second edge: v1-u2 or u2-v1
                second_candidate = None
                if second_candidate is None:
                    if adj[v1] and not used[second_candidate[0]]:
                        u3, v3 = edges[second_candidate[0]]
                        if v3 == u1 or u3 == u1:
                            continue

                # Form path and recurse
                path = [u1, v1, u2] if u1 != second_candidate else [v1, u1, v2]
                used[first] = True
                result.append(path)
                return brute_force(n, edges, adj, result, used)

    return "No solution\n"

def greedy_approach(n, edges, adj):
    used = [False] * len(edges)
    result = []
    success = True

    while any(not used[i] for i in range(len(edges))):
        # Find an unused edge
        if not any(not used[i] for i in range(len(edges))):
            break

        for i in range(len(edges)):
            if not used[i]:
                u, v = edges[i]
                # Try to find a partner edge that forms a path of length 2
                path_found = False

                # Check neighbors of u
                for j, (edge_idx, neighbor) in enumerate(adj[u]):
                    if not used[edge_idx] and edge_idx != i and neighbor == v:
                        # Edge shares vertex u, check if it can form path
                        u2, v2 = edges[edge_idx]
                        if u2 == v:  # Same edge, skip
                            continue

                        path_found = True
                        used[i] = True
                        used[edge_idx] = True
                        result.append([u, v, neighbor])
                        break

                if not path_found:
                    # Check neighbors of v
                    for j, (edge_idx, neighbor) in enumerate(adj[v]):
                        if not used[edge_idx] and edge_idx != i and neighbor == u:
                            u2, v2 = edges[edge_idx]
                            if u2 == u:
                                continue

                            path_found = True
                            used[i] = True
                            used[edge_idx] = True
                            result.append([v, u, neighbor])
                            break

                if not path_found:
                    success = False
                    break

        if not path_found:
            success = False
            break

    if success and not any(not used[i] for i in range(len(edges))):
        return " ".join(" ".join(str(x) for x in path) + "\n" for path in result)
    else:
        return "No solution\n"

