def solution(input_str):
    lines = input_str.strip().split('\n')

    # Parse first line - handle different formats (2 or 4 tokens)
    first_tokens = lines[0].split()
    n, m = int(first_tokens[0]), int(first_tokens[1])

    # Check if there are swap flags (format: n m swapLR swapUD)
    if len(first_tokens) >= 4:
        swapLR = int(first_tokens[2])
        swapUD = int(first_tokens[3])
    else:
        swapLR = 0
        swapUD = 0

    # Read grid rows
    grid = []
    for i in range(1, n + 1):
        grid.append(lines[i])

    # Find F position (1-indexed for problem compatibility)
    target = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'F':
                target = (i, j)  # 0-indexed
                break
        if target:
            break

    if target is None:
        return ""

    # Move deltas for each direction
    dr_map = {'U': -1, 'D': 1, 'L': 0, 'R': 0}
    dc_map = {'U': 0, 'D': 0, 'L': -1, 'R': 1}

    remap_U = {'U': 'D', 'D': 'U'}
    remap_LR = {'L': 'R', 'R': 'L'}

    # Apply swaps if needed
    if swapUD:
        dr_map['U'], dr_map['D'] = dr_map['D'], dr_map['U']
    if swapLR:
        dc_map['L'], dc_map['R'] = dc_map['R'], dc_map['L']

    # BFS to find shortest path
    start = (0, 0)  # Starting position (1,1) in 1-indexed

    queue = deque([(start[0], start[1], "")])  # (row, col, path)
    visited = {start}
    result_path = ""

    while queue:
        r, c, path = queue.popleft()
        if (r, c) == target:
            result_path = path
            break

        for move in ['U', 'D', 'L', 'R']:
            nr = r + dr_map[move]
            nc = c + dc_map[move]

            if 0 <= nr < n and 0 <= nc < m:
                if grid[nr][nc] != '*' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc, path + move))

    # Convert path to output format with newlines
    return result_path + '\n' if result_path else ""

