    lines = data.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(m):
        u, v = map(int, lines[1 + i].split())
        adj[u].append(v)
        adj[v].append(u)

    targets = list(map(int, lines[1 + m].split()))

    def check(pressed_set):
        """Check if pressing the given set of counters is valid."""
        for i in range(1, n + 1):
            # Final value at counter i
            val = 1 if i in pressed_set else 0
            for neighbor in adj[i]:
                if neighbor in pressed_set:
                    val += 1
            if val == targets[i - 1]:
                return False
        return True

    # Strategy 1: Try pressing all counters (when none have target == degree+1)
    if all((len(adj[i]) + 1) != targets[i - 1] for i in range(1, n + 1)):
        return f"{n}\n" + " ".join(str(i) for i in range(1, n + 1))

    # Strategy 2: Try pressing nothing (when no target is 0)
    if all(target != 0 for target in targets):
        return "0\n"

    # Strategy 3: Try pressing single counters
    for i in range(1, n + 1):
        if check({i}):
            return f"1\n{i}"

    # Strategy 4: Try pressing pairs
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if check({i, j}):
                return f"2\n{i} {j}"

    # No solution found
    return "-1"


