    tokens = input_str.strip().split()
    n, k = int(tokens[0]), int(tokens[1])

    phones = []
    idx = 2
    for i in range(n):
        s = tokens[idx]
        m = int(tokens[idx + 1])
        phones.append((s, m))
        idx += 2

    # Calculate base cost (without any speed dial)
    base_cost = sum(len(s) * m for s, m in phones)

    # Calculate saving contribution for each possible prefix
    # Each phone number s with frequency m can save if we assign a speed dial prefix
    # that matches the start of s. The saving is len(prefix) * m

    prefix_savings = {}

    for s, m in phones:
        for length in range(1, len(s) + 1):
            prefix = s[:length]
            saving = length * m
            if prefix in prefix_savings:
                prefix_savings[prefix] += saving
            else:
                prefix_savings[prefix] = saving

    # Get all saving values and sort descending
    if not prefix_savings:
        return str(base_cost)

    savings_list = sorted(prefix_savings.values(), reverse=True)

    # Take top k savings (or fewer if not enough prefixes exist)
    total_savings = sum(savings_list[:k])

    # Minimum cost = base_cost - total_savings
    return str(base_cost - total_savings)

