def is_prime(num):
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def factorize(n):
    factors = set()
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors.add(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return list(factors)

def get_primitive_roots_mod_p(p, n):
    # Find one primitive root
    prime_factors = set()
    for q in factorize(n):
        prime_factors.add(q)

    for a in range(2, p):
        is_primitive = True
        for q in prime_factors:
            if pow(a, n // q, p) == 1:
                is_primitive = False
                break
        if is_primitive:
            return [a]  # Return just one for now
    return []

