    # Primitive roots mod 2: only residue class 1 mod 2
    # So b must be odd. But we need b < x. If x <= 2, no solution.
    if p == 2 and x <= 2:
        return "-1"

    # Factorize n (which is p - 1)
    prime_factors = set(factorize(n))

    # Find all primitive roots in [2, p-1]
    primitive_roots_in_range = []
    for a in range(2, p):
        is_primitive = True
        for q in prime_factors:
            if pow(a, n // q, p) == 1:
                is_primitive = False
                break
        if is_primitive:
            primitive_roots_in_range.append(a)

    if not primitive_roots_in_range:
        return "-1"

    # For each primitive root r, find the largest b < x with b ≡ r (mod p)
    # b_r = x - 1 - ((x - 1 - r) % p)
    # Return the maximum

    rem = (x - 1) % p
    max_b = -1

    for r in primitive_roots_in_range:
        # Compute (x - 1 - r) % p
        diff = (x - 1 - r) % p
        b_r = x - 1 - diff
        if b_r > max_b:
            max_b = b_r

    # Check if max_b is valid (must be >= 2)
    if max_b < 2:
        return "-1"

    return str(max_b)

import collections
from itertools import combinations

def solution(input_str):
    lines = input_str.strip().split('\n')
    try:
        n, d = map(int, lines[0].split())
        c = list(map(int, lines[1].split()))
    except:
        return "0 0"

    total = sum(c)
    if n == 0:
        return "0 0"

    # BFS: state is frozenset of items John owns
    start = frozenset()
    visited = {start}
    queue = collections.deque([(start, 0)])

    max_value = 0
    best_days = 0

    while queue:
        state, days = queue.popleft()
        current_value = sum(c[i] for i in state)

        if current_value > max_value:
            max_value = current_value
            best_days = days

        if current_value >= total:
            break

        market = [i for i in range(n) if i not in state]

        # Option 1: Take new items (no exchange, just add)
        for size in range(len(market) + 1):
            for y in combinations(market, size):
                y_set = set(y)
                gain = sum(c[i] for i in y_set)
                if gain <= d:
                    new_state = frozenset(state | y_set)
                    if new_state not in visited:
                        visited.add(new_state)
                        queue.append((new_state, days + 1))

        # Option 2: Exchange (give up items, take new items)
        for size1 in range(1, len(state) + 1):
            for x in combinations(state, size1):
                x_set = set(x)
                for size2 in range(len(market) + 1):
                    for y in combinations(market, size2):
                        y_set = set(y)
                        if not y_set:
                            continue

                        new_state = frozenset((state - x_set) | y_set)

                        if new_state in visited:
                            continue

                        old_val = sum(c[i] for i in state)
                        new_val = sum(c[i] for i in new_state)

                        if new_val - old_val <= d:
                            visited.add(new_state)
                            queue.append((new_state, days + 1))

    return f"{max_value} {best_days}"
